[
  {
    "statement": "None of the documents found contained information about the cost-effectiveness of any methods for enhancing biodiversity on intertidal artificial structures.",
    "citations": []
  },
  {
    "statement": "The question regarding the cost-effectiveness of methods for enhancing biodiversity on intertidal artificial structures could not be answered.",
    "citations": []
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects of creating crevice habitats on subtidal artificial structures on the biodiversity of those structures.",
    "citations": [
      "3454"
    ]
  },
  {
    "statement": "No studies that directly evaluated the intervention of creating crevice habitats on subtidal artificial structures were found during literature searches.",
    "citations": [
      "3454"
    ]
  },
  {
    "statement": "There is no evidence to indicate whether or not the intervention of creating crevice habitats on subtidal artificial structures has any desirable or harmful effects.",
    "citations": [
      "3454"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects of creating large protrusions (>50 mm) on the biodiversity of subtidal artificial structures.",
    "citations": [
      "3443"
    ]
  },
  {
    "statement": "No studies were found that assessed the effects of creating large ridges or ledges (>50 mm) on subtidal artificial structures.",
    "citations": [
      "3445"
    ]
  },
  {
    "statement": "In a related context of green engineering on artificial structures, no studies were found evaluating the effects of covering subsea cables with artificial reefs on subtidal benthic invertebrate populations.",
    "citations": [
      "2255"
    ]
  },
  {
    "statement": "Due to the lack of studies, there is no evidence to indicate whether creating large protrusions, large ridges, or large ledges on subtidal artificial structures has any desirable or harmful effects.",
    "citations": [
      "2255",
      "3443",
      "3445"
    ]
  },
  {
    "statement": "Due to the lack of studies, there is no evidence to indicate whether covering subsea cables with artificial reefs has any desirable or harmful effects.",
    "citations": [
      "2255",
      "3443",
      "3445"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the public perception of reducing the slope of intertidal artificial structures for biodiversity enhancement.",
    "citations": [
      "3461",
      "3442"
    ]
  },
  {
    "statement": "Two studies in an estuary in southeast Australia looked at the effects of reducing the slope of intertidal artificial structures on biodiversity.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "One before-and-after study indicated that reducing the slope of an intertidal artificial structure, along with creating rock pools, increased the combined macroalgae, invertebrate and fish species richness on the structure.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "A replicated, controlled study in Australia found that reducing the slope of an intertidal artificial structure did not increase the abundance of macroalgae, oysters, or mobile invertebrates on the structure surfaces.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of reducing the slope of subtidal artificial structures on the biodiversity of subtidal artificial structures.",
    "citations": [
      "3442"
    ]
  }
]

[
  {
    "statement": "A study in the USA found that reducing the frequency of cleaning on subtidal artificial structures did not alter the combined invertebrate and fish community composition, species richness or diversity.",
    "citations": [
      "3447"
    ]
  },
  {
    "statement": "A study in the USA found that reducing the frequency of cleaning on subtidal artificial structures did increase macroalgal abundance.",
    "citations": [
      "3447"
    ]
  },
  {
    "statement": "A study in Australia found that reducing the area cleaned on a subtidal artificial structure increased seahorse abundance.",
    "citations": [
      "3447"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of reducing the slope of subtidal artificial structures on the biodiversity of the structures.",
    "citations": [
      "3442"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects of creating crevice habitats (>50 mm) on the biodiversity of intertidal artificial structures.",
    "citations": [
      "3437"
    ]
  },
  {
    "statement": "No studies were found that assessed the effects of creating large adjoining cavities or ‘swimthrough’ habitats (>100 mm) on the biodiversity of intertidal artificial structures.",
    "citations": [
      "3438"
    ]
  },
  {
    "statement": "A replicated, randomized, controlled study in the UK discovered that creating natural rocky reef topography on intertidal artificial structures did not lead to an increase in the combined macroalgae and invertebrate species richness on the surfaces of the structures.",
    "citations": [
      "3435"
    ]
  },
  {
    "statement": "A replicated, randomized, controlled study in the UK revealed that creating natural rocky reef topography on intertidal artificial structures had varied effects on barnacle and mobile invertebrate abundances on the surfaces, with outcomes differing by site.",
    "citations": [
      "3435"
    ]
  },
  {
    "statement": "A UK study noted that natural topography created on intertidal artificial structures was colonized by macroalgae and limpets.",
    "citations": [
      "3435"
    ]
  },
  {
    "statement": "A UK study noted that limpets utilized the shaded grooves and water-retaining depressions formed by natural topography on intertidal artificial structures.",
    "citations": [
      "3435"
    ]
  }
]

[
  {
    "statement": "Several studies have examined the ecological effects of creating 'rock pools' and other habitats on intertidal artificial structures.",
    "citations": []
  },
  {
    "statement": "Eighteen studies on creating 'rock pools' revealed that these pools can support macroalgae, mobile and non-mobile invertebrates, and fish species.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "The species supported by 'rock pools' are often otherwise absent from the surfaces of the artificial structures.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Creating 'rock pools' often increases species richness and diversity.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "The creation of hole habitats has been shown to alter community composition.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "The creation of hole habitats has been shown to increase species diversity.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "None of the reviewed documents for creating 'rock pools', 'hole habitats', or 'large adjoining cavities' on intertidal artificial structures mentioned the long-term effects of these modifications on the structural integrity of the engineering materials used in the seawalls.",
    "citations": [
      "3476",
      "3467",
      "3438"
    ]
  }
]

[
  {
    "statement": "Studies on creating textured surfaces on subtidal artificial structures show mixed results for invertebrate abundance.",
    "citations": []
  },
  {
    "statement": "One study found that creating hole habitats larger than 50 mm increased the abundance of brown crabs.",
    "citations": [
      "3434"
    ]
  },
  {
    "statement": "Creating hole habitats larger than 50 mm did not increase the abundance of other mobile invertebrates.",
    "citations": [
      "3434"
    ]
  },
  {
    "statement": "A study indicated that creating hole habitats along with pits and grooves had mixed effects on invertebrate abundance depending on the species group.",
    "citations": [
      "3434",
      "3455"
    ]
  },
  {
    "statement": "Three studies on creating short flexible habitats (1-50 mm) found mixed effects on mobile and non-mobile invertebrate abundance.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "Transplanting organisms has also shown varied outcomes.",
    "citations": []
  },
  {
    "statement": "One study on transplanting oysters did not find an increase in the combined invertebrate and fish abundance.",
    "citations": [
      "3471"
    ]
  },
  {
    "statement": "A study reported that transplanting corals did increase coral cover on structure surfaces.",
    "citations": [
      "3471"
    ]
  }
]
